CREATE DATABASE IF NOT EXISTS dualink CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dualink;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, google_sub VARCHAR(255) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, display_name VARCHAR(160), avatar_url VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(user_id,expires_at));
CREATE TABLE devices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, device_key CHAR(64) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, platform ENUM('linux','windows','web','ios','android') NOT NULL, last_seen_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE folder_mappings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, linux_path TEXT NOT NULL, windows_path TEXT NOT NULL, direction ENUM('two_way','linux_to_windows','windows_to_linux') NOT NULL DEFAULT 'two_way', safe_delete_days SMALLINT UNSIGNED NOT NULL DEFAULT 30, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE transfers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, source_device_id BIGINT UNSIGNED, target_device_id BIGINT UNSIGNED, source_path TEXT NOT NULL, target_path TEXT NOT NULL, file_name VARCHAR(512) NOT NULL, size_bytes BIGINT UNSIGNED DEFAULT 0, status ENUM('queued','uploading','ready','failed','conflict','deleted') DEFAULT 'queued', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(user_id,status));
CREATE TABLE file_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transfer_id BIGINT UNSIGNED NOT NULL, storage_key VARCHAR(700) NOT NULL, version_number INT UNSIGNED NOT NULL, size_bytes BIGINT UNSIGNED DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(transfer_id) REFERENCES transfers(id) ON DELETE CASCADE);
CREATE TABLE notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
